import type { Request, Response, NextFunction, Router } from 'express';
import express from 'express';
import { auditLog } from '../security/audit_log';
import { listConsents } from './consent';

export interface DsrAdapter {
  // Identity verification — must confirm the requester IS the data principal.
  verifyRequesterIdentity(req: Request): Promise<{ dataPrincipalId: string } | null>;

  // Aggregate everything you hold about this person. Used by §11 access.
  collectPersonalData(dataPrincipalId: string): Promise<Record<string, unknown>>;

  // Apply a correction set provided by the data principal. Used by §12 correction.
  applyCorrections(dataPrincipalId: string, changes: Record<string, unknown>): Promise<void>;

  // Soft-delete or anonymize personal data. Used by §12 erasure.
  // Returns a list of records flagged for deletion + records retained under legal hold.
  eraseOrAnonymize(dataPrincipalId: string): Promise<{ erased: string[]; retained: Array<{ category: string; reason: string }> }>;

  // Record a grievance for the grievance officer (§13).
  recordGrievance(dataPrincipalId: string, message: string): Promise<{ ticketId: string }>;

  // Record a nomination (§14).
  recordNomination(dataPrincipalId: string, nominee: { name: string; relation: string; contact: string }): Promise<void>;
}

let adapter: DsrAdapter | null = null;
export function setDsrAdapter(a: DsrAdapter): void {
  adapter = a;
}

function requireAdapter(): DsrAdapter {
  if (!adapter) throw new Error('secure-by-design: DsrAdapter not configured.');
  return adapter;
}

async function requireDataPrincipal(req: Request, res: Response): Promise<string | null> {
  const verified = await requireAdapter().verifyRequesterIdentity(req);
  if (!verified) {
    res.status(401).json({ error: 'identity_verification_required' });
    return null;
  }
  return verified.dataPrincipalId;
}

export function dsrRouter(): Router {
  const router = express.Router();
  router.use(express.json({ limit: '256kb' }));

  // DPDP §11 — Right to access information about personal data
  router.get('/access', async (req, res, next) => {
    try {
      const dpId = await requireDataPrincipal(req, res);
      if (!dpId) return;
      const [data, consents] = await Promise.all([
        requireAdapter().collectPersonalData(dpId),
        listConsents(dpId),
      ]);
      await auditLog.event('dsr.access', { actor: dpId, target: dpId });
      res.json({ personalData: data, consentHistory: consents });
    } catch (e) { next(e); }
  });

  // DPDP §12 — Right to correction, completion, updating
  router.post('/correct', async (req, res, next) => {
    try {
      const dpId = await requireDataPrincipal(req, res);
      if (!dpId) return;
      const changes = req.body?.changes;
      if (!changes || typeof changes !== 'object') {
        res.status(400).json({ error: 'changes_required' });
        return;
      }
      await requireAdapter().applyCorrections(dpId, changes);
      await auditLog.event('dsr.correct', { actor: dpId, target: dpId, fields: Object.keys(changes) });
      res.json({ ok: true });
    } catch (e) { next(e); }
  });

  // DPDP §12 — Right to erasure
  router.post('/erase', async (req, res, next) => {
    try {
      const dpId = await requireDataPrincipal(req, res);
      if (!dpId) return;
      const result = await requireAdapter().eraseOrAnonymize(dpId);
      await auditLog.event('dsr.erase', {
        actor: dpId, target: dpId,
        erasedCount: result.erased.length,
        retainedCount: result.retained.length,
      });
      // Communicate retention reasons honestly — DPDP allows retention only for
      // legal compliance or specified purposes. The user expects to know.
      res.json(result);
    } catch (e) { next(e); }
  });

  // DPDP §13 — Right to grievance redressal
  router.post('/grievance', async (req, res, next) => {
    try {
      const dpId = await requireDataPrincipal(req, res);
      if (!dpId) return;
      const message = req.body?.message;
      if (typeof message !== 'string' || message.length === 0 || message.length > 5000) {
        res.status(400).json({ error: 'message_required' });
        return;
      }
      const { ticketId } = await requireAdapter().recordGrievance(dpId, message);
      await auditLog.event('dsr.grievance', { actor: dpId, target: dpId, ticketId });
      // TODO(user): notify the grievance officer via your incident channel.
      res.status(201).json({ ticketId });
    } catch (e) { next(e); }
  });

  // DPDP §14 — Right to nominate
  router.post('/nominate', async (req, res, next) => {
    try {
      const dpId = await requireDataPrincipal(req, res);
      if (!dpId) return;
      const { name, relation, contact } = req.body ?? {};
      if (!name || !relation || !contact) {
        res.status(400).json({ error: 'nominee_fields_required' });
        return;
      }
      await requireAdapter().recordNomination(dpId, { name, relation, contact });
      await auditLog.event('dsr.nominate', { actor: dpId, target: dpId });
      res.json({ ok: true });
    } catch (e) { next(e); }
  });

  return router;
}

